{
  "diagnosis": "The option_selection module overweights the stated diagnosis and underweights patient-specific safety modifiers (renal disease, seizure history, pregnancy/bleeding risk, drug interactions), causing selection of options that are contraindicated or less safe despite matching the indication.",
  "skills": [
    {
      "id": "safety_first_selection",
      "text": "When choosing among options that all plausibly treat the stated condition, first eliminate any option that is contraindicated or higher-risk given the patient's current medicines, organ function, or comorbidity; then choose the safest remaining option that still treats the condition."
    },
    {
      "id": "route_risk_tradeoff",
      "text": "If the patient has a condition that alters drug handling or increases systemic exposure risk (e.g., renal impairment, seizure history, bleeding risk), prefer the option with the lowest systemic exposure or best-established safety profile for that patient over an equally effective but higher-risk alternative."
    },
    {
      "id": "interaction_priority",
      "text": "When the patient is already taking a medication that can interact with or compound the toxicity of a candidate option, deprioritize that candidate even if it is otherwise indicated, unless no safer indicated alternative exists."
    }
  ],
  "focus_terms": [
    "contraindicated",
    "renal impairment",
    "seizure history",
    "drug interaction",
    "systemic exposure",
    "safer alternative"
  ],
  "modules": {
    "patient_evidence": "Identify the stated condition, current medicines and relevant patient facts.",
    "safety_check": "Check patient-specific contraindications and drug interactions without inventing facts.",
    "option_selection": "Choose the option that best satisfies both indication and patient-specific safety. When multiple options are indicated, rank by patient-specific safety: eliminate contraindicated or higher-risk options first, then select the safest remaining option that still treats the condition. Prefer lower systemic exposure or better-established safety when the patient has renal impairment, seizure history, bleeding risk, or interacting current medicines."
  }
}

{
  "diagnosis": "The option_selection module fails to prioritize the option that directly treats the diagnosed condition when multiple options are plausible; it often selects a less specific or contraindicated option instead of the most indicated one.",
  "skills": [
    {
      "id": "indication_first",
      "text": "When choosing among options, first identify the option whose primary indication matches the diagnosed condition; if multiple match, prefer the one with the strongest guideline support or most direct mechanism for that condition."
    },
    {
      "id": "avoid_contraindicated",
      "text": "Exclude any option that is contraindicated or could worsen the diagnosed condition (e.g., immunosuppressants during active infection, steroids during viral infection, antidepressants during mania) before considering remaining options."
    },
    {
      "id": "symptom_targeting",
      "text": "If the diagnosed condition has a standard first-line treatment, select that option even if another option treats a related symptom; do not substitute a symptomatic treatment for a disease-modifying one unless the first-line is contraindicated."
    }
  ],
  "focus_terms": [
    "indication",
    "contraindication",
    "first-line",
    "disease-modifying",
    "symptomatic"
  ],
  "modules": {
    "patient_evidence": "Identify the stated condition, current medicines and relevant patient facts.",
    "safety_check": "Check patient-specific contraindications and drug interactions without inventing facts.",
    "option_selection": "Choose the option that best satisfies both indication and patient-specific safety. Prioritize the option whose primary indication directly matches the diagnosed condition. If multiple options are indicated, prefer the one with the strongest guideline support or most direct mechanism. Exclude any option that is contraindicated or could worsen the condition. Do not substitute a symptomatic treatment for a disease-modifying one unless the first-line is contraindicated."
  }
}

{
