    {
      "id": "indication_safety_priority",
      "text": "When choosing among options, first eliminate any option that is not indicated for the diagnosed condition. Among remaining options, prefer the one with the fewest patient-specific safety concerns (contraindications, interactions, or exacerbation of stated comorbidities). If two options are equivalent in indication and safety, choose the one that is standard first-line for the condition."
    },
    {
      "id": "avoid_contraindicated_alternatives",
      "text": "Do not select an option that is known to worsen a stated patient condition (e.g., bleeding risk, cardiovascular risk, fluid retention) when a safer indicated alternative exists."
    },
    {
      "id": "prefer_first_line_over_equivalent",
      "text": "When multiple options are indicated and safe, prefer the one that is standard first-line therapy for the diagnosed condition over alternatives that are not first-line or are used for different indications."
    }
  ],
  "focus_terms": [
    "indicated",
